options.styles:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500;600;700&display=swap');

.drill-m-card {
background: #14171D;
border-radius: 8px;
padding: 12px 14px;
border: 1.5px solid #232731;
display: flex;
flex-direction: column;
justify-content: space-between;
box-shadow: 0 4px 14px rgba(0,0,0,0.3);
height: 100%;
box-sizing: border-box;
font-family: 'Inter', sans-serif;
color: #E2E8F0;
}

.drill-m-card.state-run { border-color: rgba(16, 185, 129, 0.45); }
.drill-m-card.state-alarm { border-color: rgba(239, 68, 68, 0.85); background: linear-gradient(180deg, rgba(239, 68, 68, 0.1) 0%, #14171D 35%); }
.drill-m-card.state-stop { border-color: rgba(245, 158, 11, 0.5); }
.drill-m-card.state-warning { border-color: rgba(234, 179, 8, 0.5); }
.drill-m-card.state-standby { border-color: rgba(100, 116, 139, 0.4); }
.drill-m-card.state-offline { border: 1.5px dashed rgba(100, 116, 139, 0.45); background: #101217; }

.drill-card-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.drill-m-title { display: flex; align-items: center; gap: 8px; }
.drill-m-name { font-size: 16px; font-weight: 800; color: #F8FAFC; font-family: 'JetBrains Mono', monospace; }

.drill-status-pill { font-size: 10px; font-weight: 700; padding: 2px 7px; border-radius: 8px; display: inline-flex; align-items: center; gap: 4px; }
.state-run .drill-status-pill { background: rgba(16, 185, 129, 0.2); color: #34D399; }
.state-alarm .drill-status-pill { background: rgba(239, 68, 68, 0.25); color: #F87171; }
.state-stop .drill-status-pill { background: rgba(245, 158, 11, 0.2); color: #FBBF24; }
.state-warning .drill-status-pill { background: rgba(234, 179, 8, 0.2); color: #FDE047; }
.state-standby .drill-status-pill { background: rgba(100, 116, 139, 0.2); color: #94A3B8; }
.state-offline .drill-status-pill { background: rgba(100, 116, 139, 0.18); color: #94A3B8; border: 1px solid rgba(100, 116, 139, 0.35); }

.drill-m-timeago { font-size: 10.5px; color: #94A3B8; font-weight: 600; }
.state-offline .drill-m-timeago { color: #F97316; font-weight: 700; }

.drill-detail-table { display: flex; flex-direction: column; gap: 4px; font-size: 12px; margin-bottom: 8px; }
.drill-detail-row { display: grid; grid-template-columns: 95px 1fr; align-items: baseline; gap: 6px; }
.drill-detail-label { color: #94A3B8; font-weight: 500; font-size: 11px; }
.drill-detail-val { color: #E2E8F0; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.drill-code-val { font-family: 'JetBrains Mono', monospace; font-weight: 700; }
.state-alarm .drill-code-val { color: #F87171; }
.state-run .drill-code-val { color: #34D399; }
.drill-prog-val { font-family: 'JetBrains Mono', monospace; color: #38BDF8; font-weight: 600; }
.drill-hole-val { font-family: 'JetBrains Mono', monospace; color: #FBBF24; font-weight: 700; }
.drill-tool-val { color: #F1F5F9; font-weight: 600; }
.drill-msg-row {
grid-template-columns: 60px 1fr;
align-items: flex-start;
margin-top: 2px;
}
.drill-msg-val {
color: #CBD5E1;
font-size: 11px;
white-space: normal !important;
word-break: break-word;
line-height: 1.3;
}
.state-alarm .drill-msg-val { color: #FECACA; font-weight: 600; }

.drill-spindle-box { margin: 6px 0 8px 0; display: flex; flex-direction: column; gap: 4px; }
.drill-spindle-header { font-size: 10px; font-weight: 600; color: #94A3B8; display: flex; align-items: center; justify-content: space-between; }
.drill-spindle-sub { font-size: 9px; color: #64748B; font-family: 'JetBrains Mono', monospace; }
.drill-spindle-badges { display: flex; align-items: center; gap: 6px; }
.drill-spindle-circle { width: 18px; height: 18px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 800; font-family: 'JetBrains Mono', monospace; }
.drill-spindle-circle.is-on { background: radial-gradient(circle at 45% 38%, #86EFAC 0%, #22C55E 45%, #15803D 85%, #14532D 100%); border: 1px solid #14532D; color: #064E3B; }
.drill-spindle-circle.is-off { background: radial-gradient(circle at 45% 38%, #4A171E 0%, #2A0E13 100%); border: 1px solid #661D26; color: #D19CA4; box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.6); }
.drill-spindle-circle.is-alarm { background: radial-gradient(circle at 45% 38%, #FECACA 0%, #EF4444 45%, #B91C1C 85%, #7F1D1D 100%); border: 1px solid #7F1D1D; color: #FFFFFF; text-shadow: 0 1px 2px rgba(0, 0, 0, 0.7); box-shadow: 0 0 6px rgba(239, 68, 68, 0.6); }

.drill-mid-pills { display: flex; justify-content: space-around; align-items: center; gap: 8px; margin-bottom: 8px; background: #0E1014; padding: 4px 8px; border-radius: 4px; border: 1px solid #1E222A; }
.drill-pill-tag { font-size: 10.5px; color: #94A3B8; font-weight: 600; }
.drill-pill-val-rpm { color: #38BDF8; font-family: 'JetBrains Mono', monospace; font-weight: 700; }
.drill-pill-val-feed { color: #34D399; font-family: 'JetBrains Mono', monospace; font-weight: 700; }
.drill-pill-sep { color: #334155; font-weight: 700; }

.drill-card-footer { display: flex; align-items: center; justify-content: space-between; padding-top: 6px; border-top: 1px solid #232731; font-size: 11px; }
.drill-footer-last { color: #CBD5E1; font-family: 'JetBrains Mono', monospace; font-size: 10px; }
